function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must have the same length.';
  if (operations[0] !== 'BSTIterator' || operations.slice(1).includes('BSTIterator')) return 'Start with "BSTIterator" exactly once.';
  if (operations.length - 1 > 100000) return 'Make at most 10^5 calls after the constructor.';
  const tree = Array.isArray(args[0]) ? args[0][0] : undefined;
  if (!Array.isArray(tree) || tree.length < 1 || tree[0] === null) return 'The tree needs at least one node.';
  if (tree.some(v => v !== null && (!Number.isInteger(v) || v < 0 || v > 1000000))) return 'Node values are whole numbers from 0 to 10^6.';
  // Rebuild the tree from its level-order list.
  const nodes = [{ val: tree[0], left: null, right: null }];
  let head = 0;
  for (let i = 1; i < tree.length; i += 2) {
    if (head >= nodes.length) return 'The level-order list continues after the tree has ended.';
    const parent = nodes[head++];
    for (const [side, value] of [['left', tree[i]], ['right', tree[i + 1]]]) {
      if (value === null || value === undefined) continue;
      parent[side] = { val: value, left: null, right: null };
      nodes.push(parent[side]);
    }
  }
  if (nodes.length > 100000) return 'The tree has at most 10^5 nodes.';
  // An in-order walk of a binary search tree must be strictly increasing.
  const stack = [];
  let node = nodes[0];
  let last = -1;
  while (node || stack.length) {
    while (node) {
      stack.push(node);
      node = node.left;
    }
    node = stack.pop();
    if (node.val <= last) return 'The tree must be a binary search tree with distinct values.';
    last = node.val;
    node = node.right;
  }
  let index = -1;
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    if (!['hasNext', 'next', 'hasPrev', 'prev'].includes(op)) return `Unknown operation ${op}.`;
    if (!Array.isArray(args[i]) || args[i].length !== 0) return `${op} takes no arguments: write [].`;
    if (op === 'next') {
      if (index + 1 >= nodes.length) return 'next is only called when a next value exists.';
      index++;
    } else if (op === 'prev') {
      if (index <= 0) return 'prev is only called when a previous value exists.';
      index--;
    }
  }
  return null;
}

