class BSTIterator {
  constructor(root) {
    // Copy the whole in-order sequence up front with a recursive walk.
    this.sorted = [];
    const walk = node => {
      if (!node) return;
      walk(node.left);
      this.sorted.push(node.val);
      walk(node.right);
    };
    walk(root);
    this.cursor = -1;
  }

  hasNext() {
    return this.cursor < this.sorted.length - 1;
  }

  next() {
    this.cursor += 1;
    return this.sorted[this.cursor];
  }

  hasPrev() {
    return this.cursor >= 1;
  }

  prev() {
    this.cursor -= 1;
    return this.sorted[this.cursor];
  }
}

