function generate(rand, size) {
  const large = size === 'large';
  const pick = k => Math.floor(rand() * k);
  const n = large ? 900 : 1 + pick(8);
  const top = !large && rand() < 0.5 ? 30 : 1000000;
  const chosen = new Set();
  if (rand() < 0.3) chosen.add(0);
  if (rand() < 0.3 && n > chosen.size) chosen.add(top);
  while (chosen.size < n) chosen.add(pick(top + 1));
  const values = [...chosen];
  const style = rand();
  if (style < 0.15) values.sort((a, b) => a - b);
  else if (style < 0.25) values.sort((a, b) => b - a);
  else {
    for (let i = values.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [values[i], values[j]] = [values[j], values[i]];
    }
  }
  // Insert the values one by one to get a binary search tree of that shape.
  const root = { val: values[0], left: null, right: null };
  for (const value of values.slice(1)) {
    let node = root;
    for (;;) {
      const side = value < node.val ? 'left' : 'right';
      if (!node[side]) {
        node[side] = { val: value, left: null, right: null };
        break;
      }
      node = node[side];
    }
  }
  const tree = [];
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    if (queue[i] === null) {
      tree.push(null);
      continue;
    }
    tree.push(queue[i].val);
    queue.push(queue[i].left, queue[i].right);
  }
  while (tree[tree.length - 1] === null) tree.pop();
  const operations = ['BSTIterator'];
  const args = [[tree]];
  const calls = large ? 499 : 1 + pick(12);
  let index = -1;
  while (operations.length <= calls) {
    const roll = rand();
    let op;
    if (roll < 0.5) op = index + 1 < n ? 'next' : 'hasNext';
    else if (roll < 0.7) op = index > 0 ? 'prev' : 'hasPrev';
    else op = roll < 0.85 ? 'hasNext' : 'hasPrev';
    if (op === 'next') index++;
    if (op === 'prev') index--;
    operations.push(op);
    args.push([]);
  }
  return [operations, args];
}
